1	var store = {}
2	
3	export function getCached(key) {
4	  var entry = store[key]
5	  if (!entry) return null
6	  if (Date.now() > entry.expireAt) {
7	    delete store[key]
8	    return null
9	  }
10	  return entry.value
11	}
12	
13	export function setCache(key, value, ttlMs) {
14	  store[key] = {
15	    value: value,
16	    expireAt: Date.now() + ttlMs
17	  }
18	}
