1	import storage from "@system.storage"
2	
3	const THEME_KEY = "infoDarkMode"
4	var cachedTheme = null
5	
6	export function getThemeSync() {
7	  return cachedTheme !== null ? cachedTheme : false
8	}
9	
10	export function getTheme(callback) {
11	  if (cachedTheme !== null) {
12	    callback(cachedTheme)
13	    return
14	  }
15	  storage.get({
16	    key: THEME_KEY,
17	    success: function (data) {
18	      cachedTheme = data === "true"
19	      callback(cachedTheme)
20	    },
21	    fail: function () {
22	      cachedTheme = false
23	      callback(false)
24	    }
25	  })
26	}
27	
28	export function setTheme(isDark) {
29	  cachedTheme = isDark
