310	  var areaCode = toAreaCode(city)
311	  if (!areaCode) {
312	    return Promise.resolve({
313	      ready: false,
314	      title: city,
315	      subtitle: "未知城市",
316	      message: "未找到该城市的区域编号",
317	      details: [],
318	      indexes: [],
319	      forecasts: [],
320	      alerts: []
321	    })
322	  }
323	
324	  var query = encodeQuery({
325	    location: areaCode
326	  })
